const askedProduct =
     /\b(chahiye|chaiye|chahie|mangwana|mangana|khareed|buy|order\s*karna|lena\s*(hai|h)\b)/i.test(_pq)
  || /\b(konsa|konse|kaunsa|kaunse|kaun\s*sa|which|what)\b[^.!?]{0,24}\b(product|products|dawa|dawai|medicine|item|option|options|kit)\b/i.test(_pq)
  || /\b(product|products|dawa|dawai|medicine|kit|option|options)\b[^.!?]{0,24}\b(batao|bata|bta|dikhao|dikha|suggest|recommend|hai|\bh\b|available|milega|milta)/i.test(_pq)
  || /\b(recommend|suggest)\b/i.test(_pq)
  || /\bke\s*liye\b[^.!?]{0,24}\b(kya|konsa|konse|kaunsa|product)\b/i.test(_pq);

// Did the model actually name one of the products it was handed? Comparing on the first
// significant word of each title, because it will say "Vaji Bati" not the full Shopify name.
const _replyNamesAMatch = _matches.some(p => {
  const key = String(p.title || '').split(/[^A-Za-z0-9]+/).filter(w => w.length > 3)[0];
  return key && new RegExp(key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(String(aiText));
});

const needsPrice = askedPrice && !replyHasPrice;
// They asked for a product, we had matches, and the reply named none of them.
const ignoredTheCatalog = askedProduct && !_replyNamesAMatch && !replyHasPrice && !replyHasLink;
const needsLink = askedLink && !replyHasLink;

if (!_answered() && !doseGuard && !slotGuard && !bookingGuard && (needsPrice || needsLink || ignoredTheCatalog) && _matches.length) {
  const sellable = _matches.filter(p => !p.isRx && p.inStock);
  const rx = _matches.filter(p => p.isRx);
  const oos = _matches.filter(p => !p.isRx && !p.inStock);
  const CONSULT = 'Chahein to free consultation me doctor aapke liye best option confirm kar denge, wo free hai.';
  if (sellable.length === 1) {
    const p = sellable[0];
    aiText = _pname(p) + ' ka price ' + _rs(p.price) + ' hai ji.\n' + p.url + '\n\n' + CONSULT;
    priceGuard = ignoredTheCatalog && !needsPrice && !needsLink ? 'recommended' : 'one';
  } else if (sellable.length > 1) {
    // Two candidates is not a failure to resolve - "shilajit" genuinely matches two
    // products. Give both prices and let the customer pick (PRODUCT POLICY rule 5).
    // Numbered so they can answer "1" instead of typing a product name back.
    const [a, b] = sellable;
    aiText = 'Ji, do options hain:\n\n'
      + _productLine(a, 1) + '\n\n'
      + _productLine(b, 2) + '\n\n'
      + 'Aapko kaunsa chahiye - 1 ya 2?';
    priceGuard = ignoredTheCatalog && !needsPrice && !needsLink ? 'recommended_2' : 'ambiguous';
  } else if (rx.length) {
    aiText = rx[0].title + ' me allopathic medicine hoti hai ji, iske liye doctor ki salah zaroori hai - iska price share nahi kar sakti. 10-15 min ki free consultation kara deti hu.';
    priceGuard = 'rx';
  } else if (oos.length) {
    aiText = oos[0].title + ' abhi available nahi hai ji. Free consultation me doctor aapke liye sahi alternative bata denge, consultation aur diet plan free hai.';
    priceGuard = 'out_of_stock';
  }
  if (priceGuard) {
    console.log('[Price Guard] ' + priceGuard + ' | q=' + _pq.slice(0, 50)
      + ' | matches=' + _matches.map(p => p.title + '=' + p.price + (p.isRx ? '/Rx' : '') + (p.inStock ? '' : '/OOS')).join(', '));
  }
}

// ---- CALLBACK PROMISE GUARD ----
// "Okay ji I will share your details with the doctor and they will call you in 5 minutes"
// and "They will call you in 5 minutes ji" - the model invents a commitment nobody can keep.
// Nobody promised it in the prompt; it comes from the fine-tune, where agents used to say it.
// The callback time is the PATIENT'S choice, so a promise is replaced with the ask: name +
// a preferred time inside working hours.
// Deliberately not matched: "10-15 min free consultation" describes how long the consultation
// LASTS, which is true and useful - hence the lookbehind on a "N-M" range and the fact that
// "consultation" is not one of the call words.
let promiseGuard = false;
const _CALLWORD = '(call|phone|ring|baat|connect|contact|sampark)';
const _MINS = '(?<!\\d\\s?-\\s?)\\b\\d{1,2}\\s*(minute|minutes|min|mins|minit|minut)\\b';
const _promiseRe = new RegExp(
  _MINS + '[^.!?]{0,30}\\b' + _CALLWORD + '\\b'
  + '|\\b' + _CALLWORD + '\\b[^.!?]{0,30}' + _MINS
  + '|\\b(abhi|turant|immediately|right\\s*now|just\\s*now)\\b[^.!?]{0,26}\\b' + _CALLWORD + '\\b'
  + '|\\b' + _CALLWORD + '\\b[^.!?]{0,26}\\b(abhi|turant|immediately|right\\s*now|just\\s*now)\\b', 'i');

if (!_answered() && !doseGuard && !slotGuard && !bookingGuard && !priceGuard && _promiseRe.test(String(aiText))) {
  promiseGuard = true;
  aiText = 'Ji, main aapki free consultation set kara deti hu. Aapka naam aur kaunsa time aapke liye theek rahega bata dijiye ('
    + _hhmm(WORK_START_MIN) + ' se ' + _hhmm(WORK_END_MIN) + ' ke beech), doctor us time par call karenge.';
  console.log('[Promise Guard] replaced an invented callback promise | q=' + String(newMsgText || '').slice(0, 50));
}

// ---- SUBSTANCE GUARD ----
// A patient wrote out her full symptom history - cycle length, flow, how it changed over two
// months - and the reply was "ji". A bare acknowledgement to someone who has just described
// a health problem reads as not listening, and it is the fastest way to lose the customer.
// The tuned model does this because it was trained on agent chatter where "ji" is a filler
// turn; it has no sense of when a message deserves a real answer.
// Only fires when the customer clearly said something substantial AND the reply is pure
// filler, so short exchanges ("Okay" -> "ji") are untouched.
// A filler reply is ALSO always wrong when WE just asked a question. Production, twice in a
// row: "aapki age kitni h" -> customer "24" -> "ji". They answered us and got nothing back,
// so they repeated themselves - and got "ji" again. The old condition could never catch it,
// because it required a LONG customer message (12+ words / 70+ chars) and a factual answer
// to our own question is one or two words by definition.
let substanceGuard = false;
const _custWords = String(newMsgText || '').trim().split(/\s+/).filter(Boolean).length;
const _replyIsFiller = QR_FILLER_RE.test(String(aiText || '').trim());
const _custSaidSomething = _custWords >= 12 || String(newMsgText || '').trim().length >= 70;
const _weAskedQuestion = /\?/.test(_lastOutText)
  || /\b(bata\s*d(o|ijiye|ena)|bataiye|batao|bta\s*d(o|ijiye)|kitni|kitna|kitne|kab\s*se|kaunsa|konsa|kaun\s*sa|kya\s*problem|naam)\b/i.test(_lastOutText);
if (!_answered() && !doseGuard && !slotGuard && !bookingGuard && !priceGuard && !promiseGuard
    && _replyIsFiller && (_custSaidSomething || _weAskedQuestion)) {
  substanceGuard = _custSaidSomething ? 'long_message' : 'answered_our_question';
  aiText = _custSaidSomething
    ? 'Ji, aapne jo bataya wo maine samajh liya - aap pareshaan mat hoiye, isko manage kiya ja sakta hai. '
      + 'Free consultation me doctor aapki puri history dekh kar sahi plan batayenge, consultation aur diet plan dono free hain. '
      + 'Aap apna naam aur kaunsa time aapke liye theek rahega bata dijiye?'
    // They answered a short factual question, so acknowledge it and move to the next step
    // rather than re-explaining - BOOKING POLICY rule 5, one or two asks at a time.
    : 'Ji, note kar liya. Aap apna naam aur kaunsa time aapke liye theek rahega bata dijiye ('
      + _hhmm(WORK_START_MIN) + ' se ' + _hhmm(WORK_END_MIN) + ' ke beech), main free consultation set kara deti hu - doctor aapko sahi plan batayenge.';
  console.log('[Substance Guard] ' + substanceGuard + ' | custWords=' + _custWords
    + ' | lastOut=' + JSON.stringify(String(_lastOutText).slice(0, 40)));
}

// ---- Add the introduction EXACTLY ONCE, only on genuine first contact ----
if (!greetedBefore) {
  aiText = 'Hello ji, mai Ananya baat kar rahi hu SehatUP se. ' + (aiText || 'mai aapki kya help kar sakti hu?');
}
if (!aiText) aiText = 'ji, bataiye mai aapki kya help kar sakti hu?';

// ---- WHY THIS REPLY LOOKS THE WAY IT DOES ----
// Built here, where the flags live, and used twice: tagged onto the n8n execution so the
// list is searchable, and written to Firestore by Record AI Sent / Save AI Message so it
// outlives n8n's execution retention. Compact on purpose - "price=ambiguous", not a blob.
const _guardNames = ['scoreGuard', 'reportGuard', 'identityGuard', 'bookingGuard', 'substanceGuard',
  'nameGuard', 'claimGuard', 'doseGuard', 'slotGuard', 'priceGuard', 'promiseGuard'];
const _flagVals = { scoreGuard, reportGuard, identityGuard, bookingGuard, substanceGuard,
  nameGuard, claimGuard, doseGuard, slotGuard, priceGuard, promiseGuard };
const _flags = _guardNames.filter(k => _flagVals[k])
  .map(k => k.replace(/Guard$/, '') + (typeof _flagVals[k] === 'string' ? '=' + _flagVals[k] : ''));
if (emptyReason) _flags.push('empty=' + emptyReason);
const aiGuards = _flags.join(',');
try {
  $execution.customData.set('reply', String(aiText).slice(0, 60));
  $execution.customData.set('guards', aiGuards || 'none');
} catch (e) { /* paid feature; Tag Execution already logs when it is unavailable */ }
console.log('[Extract AI Response] guards=' + (aiGuards || 'none') + ' | reply=' + JSON.stringify(String(aiText).slice(0, 60)));

const docId = phone.replace(/[^0-9]/g, '');
return [{
  json: {
    phone,
    name,
    lastAiReply: aiText,
    aiGuards,
    lastUserMessage: newMsgText,
    docId,
    scoreGuard,
    reportGuard,
    identityGuard,
    bookingGuard,
    substanceGuard,
    nameGuard,
    claimGuard,
    doseGuard,
    slotGuard,
    priceGuard,
    promiseGuard,
    emptyReason,
    lastUpdated: new Date().toISOString()
  }
}];

// After the WhatsApp send: capture the id QuickReply returned (data.id) so the
// message doc is keyed by it - then the CF's forwarded SENT/DELIVERED/READ status
// callbacks update THIS doc in place instead of making a "Bot replied" placeholder.
const send = $input.first().json || {};
let sentId = null;
const cands = [send.id, send.messageId, send.message_id,
  send.data && send.data.id, send.data && send.data.messageId,
  send.message && send.message.id, send.result && send.result.id];
for (const c of cands) { if (c) { sentId = String(c); break; } }

const ai = $('Extract AI Response').first().json;
const now = Date.now();
const convId = String(ai.phone || '').replace(/[^0-9]/g, '');
const msgId = sentId || ('local_' + now + '_' + Math.floor(Math.random() * 1e6));

// WHY the bot said what it said, stored next to the message itself. n8n Cloud prunes
// executions, so an n8n-only record disappears exactly when you need it for a complaint that
// came in last week - and console.log lines are per-execution and not searchable across
// chats. This lands in Firestore, so it is queryable and shows in the CRM beside the reply.
// Built in Extract AI Response, where the guard flags live, so the list of guards exists in
// exactly one place.
const aiGuards = String(ai.aiGuards || '');

console.log('QR send response (first 200):', JSON.stringify(send).slice(0, 200), '| id:', sentId,
  '| guards:', aiGuards || 'none');

return [{
  json: {
    convId,
    msgId,
    id: msgId,
    phone: ai.phone,
    direction: 'out',
    aiGuards,
    // messageBy is overwritten by QuickReply's status callback ('AI' -> 'AGENT'), and so
    // is agentId - both end up identical to a human agent's CRM reply. senderKind is
    // written once here and never touched again, so it is the ONLY field that lets
    // "Decide Process" tell the AI's own replies apart from a human takeover.
    senderKind: 'AI',
    messageBy: 'AI',
    _type: 'AGENT_TEXT',
    text: ai.lastAiReply,
    status: 'SENT',
    msgTime: now,
    createdAt: new Date().toISOString()
  }
}];

